#!/usr/bin/env python
"""Copy the official split indices into splits/ as read-only, digest-checked files.

Rules:
  * PolyBench   -> one file per task, exactly one fold (kind = fixed_70_30)
  * PolyBench26 -> five files per task (kind = official_5fold)
  * OpenPoly    -> generated by us, so each file records generator_sha256

This script does NOT invent a split. If the official index file is missing it
stops and says so.
"""

from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))


def main() -> int:
    from b2.config import all_tasks

    missing = []
    for cfg in all_tasks():
        target = ROOT / cfg["split"]["path"]
        if not target.exists():
            missing.append(cfg["split"]["path"])
    if missing:
        print("official split files not yet in place:")
        for m in missing:
            print("  " + m)
        print("\nCopy them from the release deposit; do not regenerate. "
              "A split we invented is not the official protocol.")
        return 1
    print("all split files present")
    return 0


if __name__ == "__main__":
    sys.exit(main())
